/* ===== Noël 2026 : animations des slides éditoriales (transform/opacity uniquement : léger pour la TV) ===== */
@keyframes mm-defile { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes mm-float { 0%, 100% { transform: translateY(0) rotate(-1.5deg); } 50% { transform: translateY(-18px) rotate(1.5deg); } }
@keyframes mm-draw { from { stroke-dashoffset: 400; } to { stroke-dashoffset: 0; } }
@keyframes mm-pop { 0% { opacity: 0; transform: translateY(30px) scale(0.92); } 70% { opacity: 1; transform: translateY(-4px) scale(1.02); } 100% { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes mm-swing-in { from { opacity: 0; transform: translateX(120px) rotate(6deg); } to { opacity: 1; transform: translateX(0) rotate(0); } }
@keyframes mm-sheen-pass { 0% { transform: translateX(-120%) skewX(-18deg); } 60%, 100% { transform: translateX(260%) skewX(-18deg); } }
@keyframes mm-twinkle { 0%, 100% { opacity: 0.25; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1.15); } }
